package com.fitbite.service; import com.fitbite.exception.ResourceNotFoundException; import com.fitbite.repository.RecipeRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class FavoriteService { private final CurrentUserService current; private final RecipeRepository recipes; public FavoriteService(CurrentUserService current,RecipeRepository recipes){this.current=current;this.recipes=recipes;} @Transactional public boolean toggle(Long id){var u=current.get();var r=recipes.findById(id).orElseThrow(()->new ResourceNotFoundException("Recipe not found"));if(u.getFavorites().contains(r)){u.getFavorites().remove(r);return false;}u.getFavorites().add(r);return true;} public List<?> list(){var u=current.get();return u.getFavorites().stream().map(r->RecipeMapper.summary(r,true)).toList();} @Transactional public void remove(Long id){var u=current.get();recipes.findById(id).ifPresent(r->u.getFavorites().remove(r));} }
